WITH base AS (SELECT id, store_id, product_id, sale_date, units, revenue, LAST_DAY(sale_date) AS sale_date_month_end, ROUND(units, 0) AS units_rounded FROM store_sales WHERE sale_date >= TO_DATE('2023-05-07') AND units <= 38), with_windows AS (SELECT id, store_id, product_id, sale_date, units, revenue, sale_date_month_end, units_rounded, ROUND(revenue / SUM(revenue) OVER (PARTITION BY product_id, store_id), 4) AS revenue_share, LAG(units, 1) OVER w_recent AS prev_units, FIRST_VALUE(units_rounded) IGNORE NULLS OVER w_grp AS first_known_units_rounded FROM base WINDOW w_recent AS (ORDER BY revenue, id), w_grp AS (PARTITION BY product_id ORDER BY units_rounded, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)), scored AS (SELECT *, MIN(revenue_share) OVER (PARTITION BY store_id) AS store_id_min_revenue_share, STDDEV_SAMP(units_rounded) OVER (PARTITION BY store_id) AS store_id_stddev_samp_units_rounded FROM with_windows), filtered AS (SELECT *, revenue - prev_units AS revenue_minus_prev_units FROM scored WHERE product_id IN (4, 5, 6, 8)), ranked AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY revenue_minus_prev_units DESC NULLS FIRST, id) AS dedup_rank FROM filtered) x WHERE dedup_rank = 1), ranked_store_sales AS (SELECT * FROM (SELECT *, ROW_NUMBER() OVER (PARTITION BY product_id ORDER BY store_id_min_revenue_share, id) AS latest_rank FROM ranked) ranked WHERE latest_rank = 1) SELECT * FROM (SELECT id, store_id, revenue, units_rounded, revenue_minus_prev_units, revenue_share FROM ranked_store_sales) src UNPIVOT (val FOR metric_name IN (revenue, units_rounded AS UNITS_ROUNDED, revenue_minus_prev_units AS REVENUE_MINUS_PREV_UNITS, revenue_share))
